package com.lifeos.habits;import com.lifeos.habits.dto.*;import com.lifeos.shared.exception.*;import com.lifeos.users.*;import org.springframework.stereotype.Service;import java.util.*;
@Service public class HabitService{private final HabitRepository r;private final UserRepository u;public HabitService(HabitRepository r,UserRepository u){this.r=r;this.u=u;}private User user(String e){return u.findByEmail(e).orElseThrow(()->new ResourceNotFoundException("User not found"));}private Habit owned(Long id,String e){return r.findByIdAndUserId(id,user(e).getId()).orElseThrow(()->new ResourceNotFoundException("Habit not found"));}public List<HabitResponse>list(String e){return r.findAllByUserIdOrderByCreatedAtDesc(user(e).getId()).stream().map(HabitResponse::from).toList();}public HabitResponse get(Long i,String e){return HabitResponse.from(owned(i,e));}public HabitResponse create(HabitRequest q,String e){Habit h=new Habit();h.setUser(user(e));apply(h,q);return HabitResponse.from(r.save(h));}public HabitResponse update(Long i,HabitRequest q,String e){Habit h=owned(i,e);apply(h,q);return HabitResponse.from(r.save(h));}public void delete(Long i,String e){r.delete(owned(i,e));}private void apply(Habit h,HabitRequest q){if(q.longestStreak()<q.currentStreak())throw new BadRequestException("longestStreak cannot be lower than currentStreak");h.setName(q.name().trim());h.setDescription(q.description());h.setFrequency(q.frequency());h.setTargetPerWeek(q.targetPerWeek());h.setCurrentStreak(q.currentStreak());h.setLongestStreak(q.longestStreak());h.setActive(q.active());}}
